// Vendored from `@std/cli@1.0.32` (`unicode_width.ts`, `_run_length.ts`, `_data.json`),
// Copyright 2018-2026 the Deno authors, MIT license; itself ported from the `unicode-width`
// Rust crate, Copyright (c) 2015 The Rust Project Developers, MIT license.
//
// Vendored rather than imported so the npm build has zero runtime dependencies (an npm
// dependency on `@jsr/std__cli` would force every consumer to configure the JSR registry)
// and so widths stay byte-identical to the previous `@std/cli` behaviour. The tables are
// the upstream `_data.json` (Unicode 15.0.0) inlined as a constant; the logic is unchanged.

/** Run-length-encoded lookup tables (base64 data `d`, base64 run lengths `r`). */
const TABLES: readonly { d: string; r: string }[] = [
	{
		d: "AAECAwQFBgcICQoLDA0OAw8DDwkQCRESERIA",
		r: "AQEBAgEBAQEBAQEBAQEBBwEHAVABBwcBBwF4",
	},
	{
		d: "",
		r: "",
	},
	{
		d: "",
		r: "",
	},
];

function runLengthDecode({ d, r }: { d: string; r: string }): Uint8Array {
	const data = atob(d);
	const runLengths = atob(r);
	let out = "";
	for (const [i, ch] of [...runLengths].entries()) {
		out += (data[i] ?? "").repeat(ch.codePointAt(0) ?? 0);
	}
	return Uint8Array.from([...out].map((x) => x.codePointAt(0) ?? 0));
}

let tables: Uint8Array[] | null = null;

function lookupWidth(cp: number): number {
	if (!tables) tables = TABLES.map(runLengthDecode);
	const [t0, t1, t2] = tables as [Uint8Array, Uint8Array, Uint8Array];
	const t1Offset = t0[(cp >> 13) & 0xff] ?? 0;
	const t2Offset = t1[128 * t1Offset + ((cp >> 6) & 0x7f)] ?? 0;
	const packedWidths = t2[16 * t2Offset + ((cp >> 2) & 0xf)] ?? 0;
	const width = (packedWidths >> (2 * (cp & 0b11))) & 0b11;
	return width === 3 ? 1 : width;
}

const cache = new Map<string, number | null>();

function charWidth(char: string): number | null {
	const hit = cache.get(char);
	if (hit !== undefined) return hit;
	const codePoint = char.codePointAt(0) ?? 0;
	let width: number | null = null;
	if (codePoint < 0x7f) {
		width = codePoint >= 0x20 ? 1 : codePoint === 0 ? 0 : null;
	} else if (codePoint >= 0xa0) {
		width = lookupWidth(codePoint);
	}
	cache.set(char, width);
	return width;
}

/**
 * Columns `str` occupies in a terminal: CJK and emoji count 2, combining marks 0, C0/C1
 * control characters 0. ANSI escape sequences are not special-cased — their printable
 * bytes are counted, which is why colour is applied only after truncation.
 */
export function unicodeWidth(str: string): number {
	let sum = 0;
	for (const ch of str) sum += charWidth(ch) ?? 0;
	return sum;
}
